import{_ as t,a as o,o as d,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Theme Customisations","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/theme-customisations/index.md","filePath":"api/graphql-api/shop/theme-customisations/index.md","lastUpdated":1787725411000}'),s={name:"api/graphql-api/shop/theme-customisations/index.md"};function a(i,e,c,n,h,l){return d(),o("div",null,e[0]||(e[0]=[r('<h1 id="theme-customisations" tabindex="-1">Theme Customisations <a class="header-anchor" href="#theme-customisations" aria-label="Permalink to &quot;Theme Customisations&quot;">​</a></h1><p>The Theme Customisations menu exposes the configurable storefront content blocks the store owner has set up — image carousels, static content snippets, product carousels, footer link sets, and similar. A client uses it to render the same homepage / landing content the store has configured, without hard-coding it.</p><h2 id="when-you-use-it" tabindex="-1">When you use it <a class="header-anchor" href="#when-you-use-it" aria-label="Permalink to &quot;When you use it&quot;">​</a></h2><p>Fetch the list to discover every active content block for the current channel and locale, then render each block according to its <code>type</code>. The single query returns one block&#39;s details by id.</p><h2 id="how-to-render-the-home-page" tabindex="-1">How to render the home page <a class="header-anchor" href="#how-to-render-the-home-page" aria-label="Permalink to &quot;How to render the home page&quot;">​</a></h2><ol><li><strong>Fetch</strong> the <code>themeCustomizations</code> list (optionally filtered by <code>type</code>). Keep only blocks with <code>status = 1</code>.</li><li><strong>Order</strong> the blocks by <code>sortOrder</code> — that is the top-to-bottom layout order.</li><li>For each block, <strong><code>JSON.parse(translation.options)</code></strong> and render by <code>type</code>:</li></ol><table tabindex="0"><thead><tr><th>Type</th><th>How to render</th><th>Needs a second call?</th></tr></thead><tbody><tr><td><code>image_carousel</code></td><td>Render <code>options.images[]</code> as slides — <code>image</code> = source, <code>link</code> = href, <code>title</code> = alt.</td><td>No — self-contained</td></tr><tr><td><code>static_content</code></td><td>Inject <code>options.html</code> and <code>options.css</code> directly (<code>&lt;img&gt;</code> uses <code>data-src</code>).</td><td>No — self-contained</td></tr><tr><td><code>footer_links</code></td><td>Render <code>options.column_N[]</code> as footer link columns.</td><td>No — self-contained</td></tr><tr><td><code>services_content</code></td><td>Render <code>options.services[]</code> (<code>service_icon</code> / <code>title</code> / <code>description</code>).</td><td>No — self-contained</td></tr><tr><td><code>product_carousel</code></td><td>Pass <code>options.filters</code> to the <a href="/api/graphql-api/shop/queries/get-products.html"><code>products</code></a> query (as its <code>filter</code>), render the products under <code>options.title</code>.</td><td><strong>Yes → products</strong></td></tr><tr><td><code>category_carousel</code></td><td>Call <a href="/api/graphql-api/shop/queries/tree-categories.html"><code>treeCategories(parentId: options.filters.parent_id)</code></a>, render the categories under <code>options.title</code>.</td><td><strong>Yes → treeCategories</strong></td></tr></tbody></table><blockquote><p><strong>Key point:</strong> <code>image_carousel</code>, <code>static_content</code>, <code>footer_links</code> and <code>services_content</code> are self-contained — render straight from <code>options</code>. <code>product_carousel</code> and <code>category_carousel</code> are only <em>configuration</em>: their <code>options.filters</code> tell you what to query from the <code>products</code> / <code>treeCategories</code> fields — the block itself carries no products or categories.</p></blockquote><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/theme-customisations.html">Theme Customisations</a></td><td><code>themeCustomizations</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/single-theme-customisation.html">Single Theme Customisation</a></td><td><code>themeCustomization(id:)</code> query</td></tr></tbody></table><p>These are public read endpoints — they require the storefront key header but no customer Bearer token. See <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',11)]))}const m=t(s,[["render",a]]);export{u as __pageData,m as default};
